/** A looping animated diagram from public/anim (original SVG art, generated by scripts/make-anims.py). */
export function Anim({ name, caption, alt }: { name: string; caption?: string; alt?: string }) {
  return (
    <figure className="anim-figure" data-testid="lesson-anim">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={`/anim/${name}.svg`} alt={alt ?? caption ?? name.replace(/-/g, " ")} width={720} height={320} loading="lazy" decoding="async" />
      {caption ? <figcaption>{caption}</figcaption> : null}
    </figure>
  );
}
